import { writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'

import { readPieces, repository } from './pieces.mjs'

export async function syncCompose(
  directory = repository,
  profile = process.env.COMPOSE_PIECE_PROFILE,
) {
  const pieces = readPieces(directory).filter((piece) => piece.compose)
  const files = pieces.map((piece) => piece.compose)

  await writeFile(
    new URL('compose.pieces.yml', directory),
    '# Generated by pnpm compose:sync. Do not edit.\n' +
      (pieces.length
        ? `include:\n${pieces
            .map((piece) => {
              const overlay = profile && piece.composeProfiles?.[profile]

              return overlay
                ? `  - path: [${JSON.stringify(piece.compose)}, ${JSON.stringify(overlay)}]\n`
                : `  - ${JSON.stringify(piece.compose)}\n`
            })
            .join('')}`
        : 'include: []\n'),
  )

  console.log(`Compose: ${files.length} piece(s): ${files.join(', ') || 'core only'}`)

  return files
}

if (process.argv[1] === fileURLToPath(import.meta.url)) await syncCompose()
